#!/usr/bin/env python3
"""Focused offline regression harness for libsoup soup_headers_parse NUL handling.

Why this exists: this container has no meson, ninja, GLib development headers or
libsoup-2.4.pc, so the official `header-parsing` test binary cannot be built.
This harness extracts the *actual* `soup_headers_parse` function body from the
supplied target checkout and compiles it against a tiny local GLib shim, then
replays the NUL regression inputs taken from tests/header-parsing-test.c.

It is an offline focused check, not the official test suite. It never touches the
network and never modifies the checkout it reads.
"""
import argparse
import os
import re
import subprocess
import sys
import tempfile

START_MARK = "soup_headers_parse (const char *str, int len, SoupMessageHeaders *dest)"


def extract_parse(source_path: str) -> str:
    text = open(source_path, encoding="utf-8", errors="replace").read()
    pos = text.index(START_MARK)
    brace = text.index("{", pos)
    depth = 0
    end = brace
    for i in range(brace, len(text)):
        if text[i] == "{":
            depth += 1
        elif text[i] == "}":
            depth -= 1
            if depth == 0:
                end = i
                break
    return text[pos:end + 1]


SHIM = r'''
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stddef.h>

typedef int gboolean;
typedef size_t gsize;
typedef char gchar;
#ifndef TRUE
#define TRUE 1
#endif
#ifndef FALSE
#define FALSE 0
#endif
#define g_return_val_if_fail(expr, val) do { if (!(expr)) { fprintf(stderr, "g_return_val_if_fail: %s\n", #expr); return (val); } } while (0)

static void *g_malloc(size_t n) { void *p = malloc(n ? n : 1); if (!p) abort(); return p; }
static void g_free(void *p) { free(p); }

typedef struct _SoupMessageHeaders SoupMessageHeaders;

#define MAXH 64
static char *cap_names[MAXH];
static char *cap_vals[MAXH];
static int cap_n = 0;

static void soup_message_headers_append(SoupMessageHeaders *dest, const char *name, const char *value)
{
	(void)dest;
	if (cap_n < MAXH) {
		cap_names[cap_n] = strdup(name);
		cap_vals[cap_n] = strdup(value);
		cap_n++;
	}
}

static void reset_caps(void)
{
	int i;
	for (i = 0; i < cap_n; i++) { free(cap_names[i]); free(cap_vals[i]); }
	cap_n = 0;
}

static const char *cap_get(const char *name)
{
	int i;
	for (i = 0; i < cap_n; i++)
		if (strcmp(cap_names[i], name) == 0)
			return cap_vals[i];
	return NULL;
}

/* ---- actual function extracted from the checkout under test ---- */
'''

TESTS = r'''
struct Case {
	const char *desc;
	const char *data;
	int len;          /* -1 => strlen */
	int expect_ok;    /* 1 => expect TRUE, 0 => expect FALSE */
	const char *name; /* for positive header check, or NULL */
	const char *value;
};

int main(void)
{
	static const char nul_name_req[]  = "GET / HTTP/1.1\r\nHost\x00: example.com\r\n";
	static const char nul_value_req[] = "GET / HTTP/1.1\r\nHost: example\x00" "com\r\n";
	static const char nul_name_resp[] = "HTTP/1.1 200 OK\r\nF\x00oo: bar\r\n";
	static const char nul_value_resp[]= "HTTP/1.1 200 OK\r\nFoo: b\x00" "ar\r\n";
	static const char ok_req[] = "GET / HTTP/1.1\r\nHost: example.com\r\nCookie: a=b\r\n";

	struct Case cases[] = {
		{ "positive request",  ok_req,        -1, 1, "Host",   "example.com" },
		{ "positive cookie",   ok_req,        -1, 1, "Cookie", "a=b" },
		{ "NUL in request header name",  nul_name_req,   36, 0, NULL, NULL },
		{ "NUL in request header value", nul_value_req,  35, 0, NULL, NULL },
		{ "NUL in response header name",  nul_name_resp,  28, 0, NULL, NULL },
		{ "NUL in response header value", nul_value_resp, 28, 0, NULL, NULL },
	};
	int i;
	int failures = 0;

	for (i = 0; i < (int)(sizeof(cases)/sizeof(cases[0])); i++) {
		int len = cases[i].len == -1 ? (int)strlen(cases[i].data) : cases[i].len;
		int ok;
		reset_caps();
		ok = soup_headers_parse(cases[i].data, len, NULL) ? 1 : 0;
		printf("%-32s -> %s (expected %s)\n", cases[i].desc,
		       ok ? "ACCEPT" : "REJECT", cases[i].expect_ok ? "ACCEPT" : "REJECT");
		if (ok != cases[i].expect_ok) {
			printf("   FAIL: accept/reject mismatch\n");
			failures++;
			continue;
		}
		if (cases[i].name) {
			const char *v = cap_get(cases[i].name);
			if (!v || strcmp(v, cases[i].value) != 0) {
				printf("   FAIL: header %s = %s (expected %s)\n",
				       cases[i].name, v ? v : "(null)", cases[i].value);
				failures++;
			}
		}
	}

	printf("TOTAL FAILURES: %d\n", failures);
	return failures == 0 ? 0 : 1;
}
'''


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--source", default="libsoup/soup-headers.c",
                    help="path to soup-headers.c (default relative to cwd)")
    ap.add_argument("--label", default="candidate")
    ap.add_argument("--keep", action="store_true")
    args = ap.parse_args()

    if not os.path.exists(args.source):
        print(f"source not found: {args.source}", file=sys.stderr)
        return 2
    func = extract_parse(args.source)
    if "soup_headers_parse" not in func or func.count("{") != func.count("}"):
        print("failed to extract a balanced soup_headers_parse body", file=sys.stderr)
        return 2

    work = tempfile.mkdtemp(prefix="libsoup-nul-harness-")
    cfile = os.path.join(work, "harness.c")
    exe = os.path.join(work, "harness")
    with open(cfile, "w", encoding="utf-8") as fh:
        fh.write(SHIM)
        fh.write(func)
        fh.write("\n")
        fh.write(TESTS)

    compile_cmd = ["gcc", "-std=c11", "-O0", "-Wall", "-Wextra", "-o", exe, cfile]
    comp = subprocess.run(compile_cmd, capture_output=True, text=True)
    if comp.returncode != 0:
        print("compile failed:\n" + comp.stdout + comp.stderr, file=sys.stderr)
        return 2
    if comp.stderr.strip():
        print("compiler warnings:\n" + comp.stderr, file=sys.stderr)

    print(f"=== focused harness [{args.label}] source={os.path.abspath(args.source)} ===")
    run = subprocess.run([exe], capture_output=True, text=True)
    print(run.stdout, end="")
    if run.stderr:
        print(run.stderr, file=sys.stderr)
    if not args.keep:
        subprocess.run(["rm", "-rf", work])
    return run.returncode


if __name__ == "__main__":
    raise SystemExit(main())

